/**
 * SoundMirror pronunciation helper — English (US)
 *
 * English helper text is generated by pack-owned grapheme/phoneme rules. The
 * 500+ practice list is content, not a runtime pronunciation dictionary.
 * A deliberately small reviewed set protects the visible presets and control
 * examples; all other input is generated on demand by the same rule engine.
 */

import universal500 from './universal500';
import { phonemeLookup } from './phonemeSystem';
import { renderEnglishHelperWord } from './helperRenderer';
import {
  ENGLISH_PRESET_WORDS as ENGLISH_RUNTIME_WORDS,
  ENGLISH_PRESET_PHRASES as ENGLISH_RUNTIME_PHRASES,
} from './presets';

export const ENGLISH_PRESET_WORDS = Object.freeze(
  ENGLISH_RUNTIME_WORDS.map((item) => item.practice)
);

export const ENGLISH_PRESET_PHRASES = Object.freeze(
  ENGLISH_RUNTIME_PHRASES.map((item) => item.practice)
);

/**
 * Reviewed controls, not a word dictionary. This mirrors the small reviewed
 * example set used by the other completed language packs.
 */
