  sh: Object.freeze(['sh']),
  zh: Object.freeze(['zh']),
  th: Object.freeze(['th']),
  dh: Object.freeze(['dh']),
  h: Object.freeze(['h']),
  ch: Object.freeze(['ch']),
  j: Object.freeze(['j']),
  r: Object.freeze(['r']),
  l: Object.freeze(['l']),
  y: Object.freeze(['y']),
  w: Object.freeze(['w']),
  ks: Object.freeze(['k', 's']),

  an: Object.freeze(['a', 'n']),
  en: Object.freeze(['ah', 'n']),
  in: Object.freeze(['i', 'n']),
  bee: Object.freeze(['b', 'ee']),
